let markers=[];function lafka_admin_init_store_location_map(){var e=document.getElementById("lafka-shipping-areas-admin-store-map");if(!e)return;let a;try{a=JSON.parse(decodeURIComponent(lafka_admin_map_params.saved_store_address_lat_long))}catch{a=null}var o=a?new google.maps.LatLng(a.lat,a.lng):new google.maps.LatLng("-33.8688197","151.2092955");const n=new google.maps.Map(e,{zoom:12}),t=(lafka_add_marker_and_pan(n,o),n.addListener("click",l=>{lafka_add_marker_and_pan(n,l.latLng)}),document.getElementById("lafka-shipping-areas-floating-search-panel-submit").addEventListener("click",()=>{lafka_geocode_address(t,n,"")}),new google.maps.Geocoder),s=lafka_admin_map_params.store_address;document.getElementById("lafka_shipping_store_map_locate").addEventListener("click",()=>{lafka_geocode_address(t,n,s)})}function lafka_geocode_address(e,a,o){let n;n=o===""?document.getElementById("lafka-shipping-areas-search-address").value:o,e.geocode({address:n}).then(({results:t})=>{a.setCenter(t[0].geometry.location),a.setZoom(12),lafka_add_marker_and_pan(a,t[0].geometry.location),lafka_fill_input(t[0].geometry.location)}).catch(t=>alert("Geocode was not successful for the following reason: "+t))}function lafka_add_marker_and_pan(e,a){lafka_delete_markers();var o=new google.maps.Marker({position:a,map:e});e.panTo(a),markers.push(o),lafka_fill_input(a)}function lafka_delete_markers(){for(let e=0;e<markers.length;e++)markers[e].setMap(null)}function lafka_fill_input(e){document.getElementById("store_map_location").value=encodeURIComponent(JSON.stringify(e))}window.addEventListener("DOMContentLoaded",function(){lafka_admin_init_store_location_map()});
